import{_ as a,o as r,c as e,ag as d}from"./chunks/framework.CtWPcAmt.js";const g=JSON.parse('{"title":"第 10 章：验收、纠错与复盘","description":"事实核查、计算复核、文件检查、实际测试四类验收；区分「表达不好」与「任务失败」；用反馈推动修正并沉淀经验。","frontmatter":{"title":"第 10 章：验收、纠错与复盘","description":"事实核查、计算复核、文件检查、实际测试四类验收；区分「表达不好」与「任务失败」；用反馈推动修正并沉淀经验。","layout":"doc","lastUpdated":true},"headers":[],"relativePath":"guide/10-acceptance-review.md","filePath":"guide/10-acceptance-review.md","lastUpdated":null}'),l={name:"guide/10-acceptance-review.md"};function o(i,t,n,h,s,c){return r(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="第-10-章-验收、纠错与复盘" tabindex="-1">第 10 章：验收、纠错与复盘 <a class="header-anchor" href="#第-10-章-验收、纠错与复盘" aria-label="Permalink to &quot;第 10 章：验收、纠错与复盘&quot;">​</a></h1><h2 id="本章解决什么问题" tabindex="-1">本章解决什么问题 <a class="header-anchor" href="#本章解决什么问题" aria-label="Permalink to &quot;本章解决什么问题&quot;">​</a></h2><p>任务跑完了，Agent 说「已完成」。然后呢？<strong>验收是人与 Agent 协作里最关键、也最被新手跳过的一步。</strong> 本章教你四类验收方法、如何区分「表达不好」和「任务失败」、如何用验收反馈推动修正，以及如何从一次任务里沉淀下次可复用的经验。产出：<strong>任务验收与复盘记录</strong>。</p><h2 id="从一个真实场景开始" tabindex="-1">从一个真实场景开始 <a class="header-anchor" href="#从一个真实场景开始" aria-label="Permalink to &quot;从一个真实场景开始&quot;">​</a></h2><p>第 5 章实测里，一款产品的自检写着「25 项全部通过」，但实际检查发现：待办清单全部未勾选、读取范围越过了 <code>input</code>、连一个临时文件都没发现（Qoder 页）。另一款产品的自检诚实披露了自己写错路径又恢复的过程（Hermes 页）。</p><p><strong>如果你把「自检通过」当成验收，第一款的严重问题你永远不会发现。</strong> 验收必须独立于 Agent 的自检——用你自己的清单，逐项打勾。</p><h2 id="先说结论" tabindex="-1">先说结论 <a class="header-anchor" href="#先说结论" aria-label="Permalink to &quot;先说结论&quot;">​</a></h2><ol><li><strong>四类验收</strong>：事实核查（对不对）、计算复核（算不算得对）、文件检查（全不全、格式对不对）、实际测试（能不能用）；</li><li><strong>区分两种失败</strong>：「表达不好」（措辞、结构问题，改改就行）vs「任务失败」（目标没达成、事实错误、边界违规，要重做）——处理方式完全不同；</li><li><strong>验收反馈要具体</strong>：「第二页的数据错了，来源是材料 X，请改为 Y」比「你做得不对」有效百倍；</li><li><strong>复盘沉淀三样东西</strong>：模板/清单更新、Skill 候选、Harness 改进点（为第四、五篇铺路）；</li><li><strong>可验收的才是可委派的</strong>：第 7 章任务卡的验收标准字段，在这里兑现。</li></ol><h2 id="必要概念" tabindex="-1">必要概念 <a class="header-anchor" href="#必要概念" aria-label="Permalink to &quot;必要概念&quot;">​</a></h2><ul><li><strong>事实核查（Fact check）</strong>：核对输出中的事实、数字、来源是否真实准确。Agent 可能幻觉（第 2 章），所以数字和来源必须查。</li><li><strong>文件检查（File check）</strong>：核对交付物是否存在、数量是否齐全、格式是否符合要求、位置是否正确。</li><li><strong>实际测试（Actual test）</strong>：让交付物在真实场景里跑一遍（打开文档、运行脚本、试用界面）。</li><li><strong>复盘（Retrospective）</strong>：任务结束后回顾「哪些做得好、哪些浪费了、下次怎么改进」。白话解释：打完仗开个总结会。</li></ul><h2 id="验收清单-四类" tabindex="-1">验收清单（四类） <a class="header-anchor" href="#验收清单-四类" aria-label="Permalink to &quot;验收清单（四类）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类别</th><th>检查项</th><th>怎么查</th></tr></thead><tbody><tr><td>事实</td><td>数字/日期/来源是否真实</td><td>对照原始材料；可疑处单独核对</td></tr><tr><td>事实</td><td>是否区分「已验证」与「推测」</td><td>看输出有没有标注</td></tr><tr><td>计算</td><td>统计、合计、比例是否算对</td><td>抽查重算；用表格工具复核</td></tr><tr><td>文件</td><td>交付物数量与名称</td><td>对照任务卡交付物清单逐项勾</td></tr><tr><td>文件</td><td>格式/结构是否符合要求</td><td>打开检查标题层级、表格、命名</td></tr><tr><td>文件</td><td>是否落在指定目录</td><td>检查 output/ 目录</td></tr><tr><td>边界</td><td>是否只读了允许范围</td><td>看过程日志/变更记录（第 9 章）</td></tr><tr><td>测试</td><td>文档能否打开渲染</td><td>实际打开</td></tr><tr><td>测试</td><td>表格/清单能否直接使用</td><td>实际操作一遍</td></tr></tbody></table><h2 id="跟着做-完成一次验收与复盘" tabindex="-1">跟着做：完成一次验收与复盘 <a class="header-anchor" href="#跟着做-完成一次验收与复盘" aria-label="Permalink to &quot;跟着做：完成一次验收与复盘&quot;">​</a></h2><h3 id="第一步-对照验收标准逐项打勾" tabindex="-1">第一步：对照验收标准逐项打勾 <a class="header-anchor" href="#第一步-对照验收标准逐项打勾" aria-label="Permalink to &quot;第一步：对照验收标准逐项打勾&quot;">​</a></h3><p>把任务卡的验收标准拿出来，逐项检查，<strong>不要看 Agent 的自检结论，只看实际产物</strong>。每项标 ✅ / ❌ / ⚠️。</p><h3 id="第二步-区分失败类型" tabindex="-1">第二步：区分失败类型 <a class="header-anchor" href="#第二步-区分失败类型" aria-label="Permalink to &quot;第二步：区分失败类型&quot;">​</a></h3><ul><li><strong>表达不好</strong>（改改就行）：措辞生硬、结构乱、示例不合适 → 让 Agent 修改，不改目标；</li><li><strong>任务失败</strong>（要重做/部分重做）：事实错误、漏交付、越界、格式完全不符 → 修正任务卡后重跑，或人工修补。</li></ul><h3 id="第三步-写具体的修正反馈" tabindex="-1">第三步：写具体的修正反馈 <a class="header-anchor" href="#第三步-写具体的修正反馈" aria-label="Permalink to &quot;第三步：写具体的修正反馈&quot;">​</a></h3><p>格式：<strong>位置 + 问题 + 期望</strong>。例：「<code>02-information-gaps.md</code> 第 3 节把 D-05 标成了『事实』，但材料里没有来源，请改为『推断』并加说明。」</p><h3 id="第四步-复核修正结果" tabindex="-1">第四步：复核修正结果 <a class="header-anchor" href="#第四步-复核修正结果" aria-label="Permalink to &quot;第四步：复核修正结果&quot;">​</a></h3><p>Agent 改完后，<strong>只检查修正点</strong>（避免被带着走），确认后再验收。</p><h3 id="第五步-写复盘记录" tabindex="-1">第五步：写复盘记录 <a class="header-anchor" href="#第五步-写复盘记录" aria-label="Permalink to &quot;第五步：写复盘记录&quot;">​</a></h3><table tabindex="0"><thead><tr><th>复盘项</th><th>记录</th></tr></thead><tbody><tr><td>Agent 做得好/差的地方</td><td></td></tr><tr><td>人必须介入的地方</td><td></td></tr><tr><td>下次可省略或自动化的步骤</td><td></td></tr><tr><td>可沉淀的模板/Skill/Harness 组件</td><td></td></tr><tr><td>任务卡/权限卡的改进点</td><td></td></tr></tbody></table><h2 id="一个完整示例-验收记录节选" tabindex="-1">一个完整示例（验收记录节选） <a class="header-anchor" href="#一个完整示例-验收记录节选" aria-label="Permalink to &quot;一个完整示例（验收记录节选）&quot;">​</a></h2><p>以第 5 章统一基准任务的验收为例（完整验收在 <code>research/runs/*/run-record.md</code>）：</p><ul><li>任务：6 份交付物 + 自检（L1）；</li><li>验收：6/6 文件存在 ✅；输入哈希 7/7 与基线一致 ✅（文件检查）；内容对照材料抽查 ✅；<strong>边界检查 ❌</strong>——读取范围记录显示越过了 <code>input</code>（Qoder/Hermes）；</li><li>失败类型判断：交付物内容合格，但<strong>边界违规</strong>属于「部分任务失败」（过程不合规）；</li><li>修正反馈：不需要重做产物，但验收记录中单独标注「过程越界」，并在教程中提示该产品「效率与边界分开评价」；</li><li>复盘沉淀：①验收清单新增「边界检查」项（看读取记录，不只看结果）；②各产品的边界表现成为第 6 章选择表「边界」维度的数据来源；③「无弹窗 ≠ 合规」成为第 8 章的安全原则。</li></ul><p>这个例子说明：<strong>验收不是「打勾通过」，而是把发现的问题变成规则和资产。</strong></p><h2 id="常见错误与恢复方法" tabindex="-1">常见错误与恢复方法 <a class="header-anchor" href="#常见错误与恢复方法" aria-label="Permalink to &quot;常见错误与恢复方法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>可能原因</th><th>怎样修正</th></tr></thead><tbody><tr><td>把自检当验收</td><td>图省事</td><td>用独立清单逐项查，自检仅供参考</td></tr><tr><td>「感觉不对但说不出哪不对」</td><td>没按清单查</td><td>按四类清单逐项过，问题会自己浮出来</td></tr><tr><td>修正后整体重查一遍</td><td>浪费且易被带偏</td><td>只查修正点</td></tr><tr><td>数据错了没发现</td><td>事实核查缺失</td><td>涉及数字一律对照来源</td></tr><tr><td>复盘就是「下次注意」</td><td>太虚</td><td>落到「更新哪个清单/模板」的具体动作</td></tr></tbody></table><h2 id="安全提醒" tabindex="-1">安全提醒 <a class="header-anchor" href="#安全提醒" aria-label="Permalink to &quot;安全提醒&quot;">​</a></h2><ul><li>涉及<strong>财务、医疗、法律</strong>的输出：验收时必须有专业复核，四类验收只是基础；</li><li>涉及<strong>对外发布</strong>：验收合格 ≠ 可以发布，发布动作永远人工执行；</li><li>验收时发现敏感数据泄漏（如产物里出现账号信息），立即删除并修改任务卡约束。</li></ul><h2 id="本章练习" tabindex="-1">本章练习 <a class="header-anchor" href="#本章练习" aria-label="Permalink to &quot;本章练习&quot;">​</a></h2><p>30 分钟：用验收清单验收你上一个真实任务的交付物（或重跑序章任务），完成一份「任务验收与复盘记录」。重点：找到至少 1 个 Agent 自检没发现的问题，并把它变成一条可复用的检查项。</p><h2 id="你应该带走的成果" tabindex="-1">你应该带走的成果 <a class="header-anchor" href="#你应该带走的成果" aria-label="Permalink to &quot;你应该带走的成果&quot;">​</a></h2><ul><li><strong>任务验收与复盘记录</strong>（四类验收结果 + 失败类型 + 修正反馈 + 复盘沉淀）。</li></ul><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><ol><li>验收独立于自检：事实、计算、文件、测试四类；</li><li>「表达不好」改改就行，「任务失败」要重做；</li><li>修正反馈要具体：位置 + 问题 + 期望；</li><li>复盘把经验变成清单、模板与 Skill 候选；</li><li>至此你已走通「任务卡 → 安全边界 → 过程跟进 → 验收复盘」的完整闭环（第三篇完成）。</li></ol>',37)])])}const b=a(l,[["render",o]]);export{g as __pageData,b as default};
